script:
let distributorInfo = [
{title: "Distributor Name", name: "distributor_name"},
{title: "Distributor Contact", name: "distributor_contact_number"}, 
{title: "Distributor Company Address", name: "distributor_company_address"},
{title: "Distributor Company", name: "distributor_company_name"},
{title: "Course Name", name: "course_name"},
{title: "Course Status", name: "completion_status"},
{title: "Documents Status", name: "submitted_documents"},
];

let table = root_element.querySelector('.distributor_table');
let heading_container = root_element.querySelector('.heading_container');
let distributor_table_body = root_element.querySelector('.distributor_table_body');

render_titles();
function render_titles(){
    distributorInfo.forEach(info =>{
        let th = document.createElement('th');
        th.innerText = info.title;
        heading_container.appendChild(th);
    })
}

const refreshButton = root_element.querySelector("button#refresh");
refreshButton.addEventListener("click", ()=>{
    console.log("clicked")
    RefreshData();
})

RefreshData();
function RefreshData(){
    distributor_table_body.innerHTML = '';
    frappe.call({
        method: "lms.overrides.dashboardapi.get_distributor_dashboard_info", 
        callback: function(response) {
            if (response.message) {
                console.log("Server response:", response.message);
                let distributors = response.message;
                distributors.sort((a, b) => {
                  let companyA = a.distributor_company?.trim() || '';
                  let companyB = b.distributor_company?.trim() || '';

                  if (!companyA && !companyB) return 0;
                  if (!companyA) return 1;  // a is empty/null → move after b
                  if (!companyB) return -1; // b is empty/null → move after a

                  return companyA.localeCompare(companyB);
                });
                updateDistributorsData(response.message);
            } else {
                console.error("Error calling whitelisted method:", response);
            }
        },
        error: function(err) { 
            console.error("AJAX call failed:", err);
        }
});
}
function updateDistributorsData(data){

    data.forEach(distributor => {
        distributor_table_body.appendChild(formated(distributor));
    })
}

// formatting utils functtions
function formated(distributor){
        let tr = document.createElement("tr");
        distributorInfo.forEach(info =>{
            tr.appendChild(styledElement(info, distributor));
        })

        return tr;
}


function styledElement(cellInfo , distributor){
    let cell = document.createElement("td");
    if(cellInfo.title =="Documents Status"){
        let e1 = document.createElement("span");
        if(!distributor["submitted_documents"]){
            e1.innerText = "pending";
            e1.classList.add("badge", "badge-secondary", "text-uppercase"); 
            cell.appendChild(e1);
        }else{
            e1.innerText = "submitted";
            e1.classList.add("badge",  "badge-success", "text-uppercase");
            cell.appendChild(e1);
            let e2 = document.createElement("span");
            let formatted = formateTime(distributor.submission_datetime);
            e2.innerText = formatted;
            e2.classList.add("datetime");
            cell.appendChild(e2);
        }
    }else if(cellInfo.title =="Distributor Contact"){
          let e1 = document.createElement("span");
          let e2 = document.createElement("span");
          e1.innerText = distributor["distributor_contact_number"];
          e2.innerText = distributor["distributor_email_address"];
          e1.classList.add("distributor_contact_number");
          e2.classList.add("distributor_email_address");
          cell.appendChild(e1);
          cell.appendChild(e2);
          cell.classList.add("small")
    }else if(cellInfo.title == "Course Status"){ 
        let e1 = document.createElement("span");
        if(distributor["completion_status"]=="Completed"){
            e1.innerText = "Completed";
            e1.classList.add("badge",  "badge-success", "text-uppercase");
            let e2 = document.createElement("span");
            let formatted = formateTime(distributor.completed_on);
            e2.innerText = formatted;
            e2.classList.add("datetime");
            cell.appendChild(e1);
            cell.appendChild(e2);
            }else if(distributor["completion_status"]=="Active"){
                e1.innerText = "Active";
                 let e2 = document.createElement("progress");
                 e2.max = 100;     
                 e2.value = distributor["progress"];
                 e2.classList.add("d-block");
                 e2.innerText = distributor["progress"];
                e1.classList.add("badge", "bg-warning", "text-uppercase"); 
                cell.appendChild(e1);
                cell.appendChild(e2);
            }else if(distributor["completion_status"]=="Re-enrolled"){
                e1.innerText = "Re Enrolled";
                e1.classList.add("badge", "badge-success", "text-uppercase"); 
                cell.appendChild(e1);
            }else{
                e1.innerText = "Pending";
                e1.classList.add("badge", "badge-secondary", "text-uppercase"); 
                cell.appendChild(e1);
            }
    }else{
        cell.innerText = distributor[cellInfo.name];
    }

    return cell;
}


//eg..  datetimeStr = "2025-08-07 11:15:50.336239"
// return 07 August 2025 11:15 AM
function formateTime(datetimeStr){
let date = new Date(datetimeStr.split('.')[0].replace(' ', 'T'));

const monthNames = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December"
];

let month = monthNames[date.getMonth()];
let day = String(date.getDate()).padStart(2, '0');
let year = date.getFullYear();

let hours = date.getHours();
let minutes = String(date.getMinutes()).padStart(2, '0');
let ampm = hours >= 12 ? 'PM' : 'AM';
hours = hours % 12 || 12;
hours = String(hours).padStart(2, '0');

let formatted = `${day} ${month} ${year} ${hours}:${minutes} ${ampm}`;

return formatted;
}

